exercises.solutionCode:
#include <stdint.h>
#include <stddef.h>

typedef enum {
    EXTI_TRIG_NONE = 0,
    EXTI_TRIG_RISING = 1,
    EXTI_TRIG_FALLING = 2,
    EXTI_TRIG_BOTH = 3
} ExtiTrigger;

int exti_config_trigger(uint32_t *rtsr, uint32_t *ftsr, unsigned int line, ExtiTrigger trigger)
{
    uint32_t mask;

    if (rtsr == NULL || ftsr == NULL || line > 31u) {
        return -1;
    }
    if (trigger != EXTI_TRIG_NONE && trigger != EXTI_TRIG_RISING &&
        trigger != EXTI_TRIG_FALLING && trigger != EXTI_TRIG_BOTH) {
        return -1;
    }

    mask = 1u << line;

    /* 先清掉该线的旧配置，避免只用 |= 时出现“只增不减”的残留 */
    *rtsr &= ~mask;
    *ftsr &= ~mask;

    if (trigger == EXTI_TRIG_RISING || trigger == EXTI_TRIG_BOTH) {
        *rtsr |= mask;
    }
    if (trigger == EXTI_TRIG_FALLING || trigger == EXTI_TRIG_BOTH) {
        *ftsr |= mask;
    }

    return 0;
}
